package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen3Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        writer = new StringWriter();
    }



    @Test
    public void testTranslate_DecimalEntity() throws IOException {
        String input = "&#123;";
        // index 0: '&', index 1: '#', start = 2, end = 5 (at ';')
        // isHex = false
        // entityValue = 123
        // return = 2 + (5 - 2) + 0 + 1 = 6
        int result = unescaper.translate(input, 0, writer);
        assertEquals(6, result);
        // Note: out.write(int) writes a single character
        assertEquals(String.valueOf((char) 123), writer.toString());
    }












}

package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen3Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        writer = new StringWriter();
    }





    @Test
    public void testTranslate_HexEntityLowercaseX() throws IOException {
        String input = "&#x1A;";
        // index 0: '&', index 1: '#', start = 2, firstChar = 'x', start becomes 3, isHex = true
        // end = 5 (at ';')
        // entityValue = Integer.parseInt("1A", 16) = 26
        // return = 2 + (5 - 3) + 1 + 1 = 6
        int result = unescaper.translate(input, 0, writer);
        assertEquals(6, result);
        assertEquals(String.valueOf((char) 26), writer.toString());
    }










}

package org.apache.commons.lang3.text.translate;

